  private async batchWrite(rows: readonly BattleQuery[], kind: 'insert'|'update'|'delete', options: BatchOptions): Promise<BatchResult> { const database=this.binding.resolve(); const requests: BatchRequest[]=[]; for (const row of rows) { row.using(database); requests.push({ plan: await database.plan(row.requestShape(kind)), params: row.parameters() }); } return batchWrite(database, requests, kind, options); }
