  public async paginate(page: number, per: number): Promise<Page<BattleRow>> { if(!Number.isSafeInteger(page)||page<1||!Number.isSafeInteger(per)||per<1) throw new OrmError('IR_INVALID','paginate requires page >= 1 and per > 0'); const saved=this.request.ir.limit; this.limit((page-1)*per,per); const result=await this.terminal('paginate') as {rows: unknown;total:number}; this.request.ir.limit=saved; const items=result.rows instanceof Collection?result.rows:new Collection<BattleRow>(); return new Page(items,result.total,Math.ceil(result.total/per),page,per); }
  public async getsAfter(cursor: string, per: number): Promise<KeysetPage<BattleRow>> { this.keyset('after',cursor,per,['seq']); const rows=await this.terminalRows(); const items=rowCollection<BattleRow>(rows, rows.plan.steps[0]!.assemble!); return keysetPage(rows,items,this.request.ir.order ?? []); }
  public async getsBefore(cursor: string, per: number): Promise<KeysetPage<BattleRow>> { this.keyset('before',cursor,per,['seq']); const rows=await this.terminalRows(); for(let left=0,right=rows.data.length-1;left<right;left++,right--){ const value=rows.data[left]!; rows.data[left]=rows.data[right]!; rows.data[right]=value; } const items=rowCollection<BattleRow>(rows, rows.plan.steps[0]!.assemble!); return keysetPage(rows,items,this.request.ir.order ?? []); }
